    /// <summary>Geometria do ícone pelo nome (Pascal case, como as propriedades abaixo); null se não existir.</summary>
    public static Geometry? Obter(string nome)
    {
        lock (_cache)
        {
            if (_cache.TryGetValue(nome, out var g)) return g;
            if (!Dados.TryGetValue(nome, out var d)) return null;
            return _cache[nome] = Geometry.Parse(d);
        }
    }

